import{_ as e,o as a,c as r,ak as d}from"./chunks/framework.DJ-92fJv.js";const b=JSON.parse('{"title":"🛠️ 服务管理","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"features/service-manager.md","filePath":"features/service-manager.md"}'),n={name:"features/service-manager.md"};function l(s,t,o,i,c,h){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="🛠️-服务管理" tabindex="-1">🛠️ 服务管理 <a class="header-anchor" href="#🛠️-服务管理" aria-label="Permalink to “🛠️ 服务管理”">​</a></h1><p><strong>主菜单选项：<code>6</code></strong></p><p>服务管理允许你单独控制噢易学生端的各个后台服务，精细化管理电脑的运行状态。</p><h2 id="可管理的服务" tabindex="-1">可管理的服务 <a class="header-anchor" href="#可管理的服务" aria-label="Permalink to “可管理的服务”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">编号</th><th>服务名</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td><strong>MMPC</strong></td><td>学生端根服务 — 学生端的核心服务，控制所有子模块</td></tr><tr><td style="text-align:center;">2</td><td><strong>OeNetlimit</strong></td><td>网络限制服务 — 负责网络访问过滤和封锁</td></tr><tr><td style="text-align:center;">3</td><td><strong>easyusbflt</strong></td><td>USB管控服务 — 负责USB存储设备的禁用控制</td></tr></tbody></table><h2 id="支持的操作" tabindex="-1">支持的操作 <a class="header-anchor" href="#支持的操作" aria-label="Permalink to “支持的操作”">​</a></h2><p>对每个服务，你可以执行以下操作：</p><table tabindex="0"><thead><tr><th style="text-align:center;">操作</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>停止</strong></td><td>临时停止服务运行，重启电脑后可能自动恢复</td></tr><tr><td style="text-align:center;"><strong>启动</strong></td><td>重新启动已停止的服务</td></tr><tr><td style="text-align:center;"><strong>重启</strong></td><td>先停止再启动，用于让服务重新加载配置</td></tr><tr><td style="text-align:center;"><strong>删除</strong></td><td><strong>从系统中彻底移除该服务</strong>，重启后也不会自动恢复</td></tr></tbody></table><h2 id="批量操作" tabindex="-1">批量操作 <a class="header-anchor" href="#批量操作" aria-label="Permalink to “批量操作”">​</a></h2><p>选项 <code>4</code> <strong>停止所有服务</strong> — 一键停止以上所有三个服务。</p><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to “使用场景”">​</a></h2><ul><li>🎯 网络解锁后又恢复 → 检查 <code>OeNetlimit</code> 是否又启动了，直接<strong>删除</strong>它</li><li>🎯 想彻底摆脱学生端 → <strong>删除</strong> <code>MMPC</code> 服务（谨慎操作）</li><li>🎯 USB解锁后又失效 → 检查 <code>easyusbflt</code> 服务状态</li><li>🎯 测试不同组合 → 分别停止某个服务观察效果</li></ul><h2 id="执行方式" tabindex="-1">执行方式 <a class="header-anchor" href="#执行方式" aria-label="Permalink to “执行方式”">​</a></h2><p>选择服务后，会有 <strong>5 秒倒计时</strong>，你可以按任意键立即开始执行。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h2><div class="danger custom-block"><p class="custom-block-title">谨慎操作</p><ul><li><strong>删除服务是永久性操作</strong>，一旦删除，只有重新安装噢易软件才能恢复。</li><li>如果只是想临时绕过限制，使用「停止」即可。</li><li>删除 <code>MMPC</code> 服务可能导致学生端无法正常运行，老师端可能会显示该机器离线。</li></ul></div>',16)])])}const p=e(n,[["render",l]]);export{b as __pageData,p as default};
